// Per-channel item store with shared/private visibility.
//
// Generic on purpose (like the relay itself): an "item" is an opaque JSON
// object (`data`) plus relay-managed metadata. The QLab viewer uses it for
// custom cues, but nothing here knows about cues.
//
// Visibility model
//   shared  — visible to every subscriber of the channel. Only clients that
//             presented the editor token may create/change/delete them.
//   private — visible only to the client that owns it. Ownership is a
//             random "owner key" generated by the client; we store only its
//             SHA-256, so the data file never contains a usable secret and the
//             hash is never sent to clients (they get a `mine` boolean).
//
// Persistence
//   One JSON file per channel in DATA_DIR, named by a hash of the channel name
//   (channel names may contain anything, and act as a weak secret when
//   subscribers are public, so we don't leak them into filenames). Writes are
//   debounced and atomic (write tmp → rename) so a crash mid-write can't leave
//   a truncated file.

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

export const DEFAULT_LIMITS = Object.freeze({
  maxItemsPerChannel: 2000,
  maxPrivatePerOwner: 300,
  maxItemBytes: 4096,
});

const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;

export function hashOwnerKey(key) {
  return crypto.createHash('sha256').update(`owner:${key}`).digest('hex');
}

function channelFile(dataDir, channel) {
  const h = crypto.createHash('sha256').update(channel).digest('hex').slice(0, 32);
  return path.join(dataDir, `items-${h}.json`);
}

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// What a given viewer is allowed to know about an item.
export function viewOf(item, viewer) {
  return {
    id: item.id,
    visibility: item.visibility,
    mine: item.visibility === 'private'
      ? item.owner === viewer.ownerHash
      : false,
    data: item.data,
    createdAt: item.createdAt,
    updatedAt: item.updatedAt,
  };
}

export function canSee(item, viewer) {
  if (item.visibility === 'shared') return true;
  return !!viewer.ownerHash && item.owner === viewer.ownerHash;
}

// Permission to move an item from `prev` (may be undefined) to `next`
// visibility. Both sides are checked so nobody can hijack a shared item by
// flipping it private, or steal someone's private item by id.
function checkWrite(prev, nextVisibility, viewer) {
  if (prev) {
    if (prev.visibility === 'shared' && !viewer.editor) return 'shared items require the editor password';
    if (prev.visibility === 'private' && prev.owner !== viewer.ownerHash) return 'not your item';
  }
  if (nextVisibility === 'shared' && !viewer.editor) return 'shared items require the editor password';
  if (nextVisibility === 'private' && !viewer.ownerHash) return 'private items require an owner key';
  return null;
}

export class ChannelItems {
  constructor(channel, file, limits, onDirty) {
    this.channel = channel;
    this.file = file;
    this.limits = limits;
    this.onDirty = onDirty;
    this.items = new Map();
  }

  list(viewer) {
    const out = [];
    for (const item of this.items.values()) if (canSee(item, viewer)) out.push(viewOf(item, viewer));
    return out;
  }

  upsert(viewer, input) {
    if (!isPlainObject(input)) return { ok: false, error: 'item must be an object' };
    const { visibility } = input;
    if (visibility !== 'shared' && visibility !== 'private') {
      return { ok: false, error: 'visibility must be "shared" or "private"' };
    }
    if (!isPlainObject(input.data)) return { ok: false, error: 'data must be an object' };
    if (Buffer.byteLength(JSON.stringify(input.data)) > this.limits.maxItemBytes) {
      return { ok: false, error: `data exceeds ${this.limits.maxItemBytes} bytes` };
    }

    let id = input.id;
    if (id !== undefined && (typeof id !== 'string' || !ID_RE.test(id))) {
      return { ok: false, error: 'invalid id' };
    }
    const prev = id ? this.items.get(id) : undefined;
    const denied = checkWrite(prev, visibility, viewer);
    if (denied) return { ok: false, error: denied };

    if (!prev) {
      if (this.items.size >= this.limits.maxItemsPerChannel) {
        return { ok: false, error: 'channel item limit reached' };
      }
      id = id ?? crypto.randomUUID();
    }
    if (visibility === 'private' && (!prev || prev.visibility !== 'private')) {
      let mineCount = 0;
      for (const it of this.items.values()) if (it.owner === viewer.ownerHash) mineCount++;
      if (mineCount >= this.limits.maxPrivatePerOwner) {
        return { ok: false, error: 'private item limit reached' };
      }
    }

    const now = Date.now();
    const item = {
      id,
      visibility,
      owner: visibility === 'private' ? viewer.ownerHash : null,
      data: input.data,
      createdAt: prev?.createdAt ?? now,
      updatedAt: now,
    };
    this.items.set(id, item);
    this.onDirty(this);
    return { ok: true, prev, item };
  }

  remove(viewer, id) {
    const prev = typeof id === 'string' ? this.items.get(id) : undefined;
    if (!prev) return { ok: false, error: 'no such item' };
    const denied = checkWrite(prev, prev.visibility, viewer);
    if (denied) return { ok: false, error: denied };
    this.items.delete(id);
    this.onDirty(this);
    return { ok: true, prev };
  }

  toJSON() {
    return { channel: this.channel, version: 1, items: [...this.items.values()] };
  }
}

export class ItemStore {
  constructor({ dataDir, limits = DEFAULT_LIMITS, saveDelayMs = 300, log = console } = {}) {
    this.dataDir = dataDir;
    this.limits = { ...DEFAULT_LIMITS, ...limits };
    this.saveDelayMs = saveDelayMs;
    this.log = log;
    this.channels = new Map();
    this.pending = new Map();   // channel -> timeout
    fs.mkdirSync(dataDir, { recursive: true });
  }

  get(channel) {
    let ch = this.channels.get(channel);
    if (ch) return ch;
    const file = channelFile(this.dataDir, channel);
    ch = new ChannelItems(channel, file, this.limits, (c) => this.scheduleSave(c));
    try {
      const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
      for (const it of raw.items ?? []) ch.items.set(it.id, it);
    } catch (err) {
      if (err.code !== 'ENOENT') this.log.error(`[items] failed to load ${file}: ${err.message}`);
    }
    this.channels.set(channel, ch);
    return ch;
  }

  scheduleSave(ch) {
    if (this.pending.has(ch.channel)) return;
    this.pending.set(ch.channel, setTimeout(() => {
      this.pending.delete(ch.channel);
      this.writeNow(ch);
    }, this.saveDelayMs));
  }

  writeNow(ch) {
    const tmp = `${ch.file}.${process.pid}.tmp`;
    try {
      fs.writeFileSync(tmp, JSON.stringify(ch.toJSON()));
      fs.renameSync(tmp, ch.file);
    } catch (err) {
      this.log.error(`[items] failed to save ${ch.file}: ${err.message}`);
    }
  }

  flush() {
    for (const [name, t] of this.pending) {
      clearTimeout(t);
      this.writeNow(this.channels.get(name));
    }
    this.pending.clear();
  }
}
